    self,
    *items: Any,
    indent: str = "    ",
    comment: str | None = None,
    add_comma: bool = True,
    newline: bool = True,
) -> None:
    """Add multiple items in a line to control the format precisely.
    When add_comma is True, only accept actual values and
    ", " will be added between values automatically.

    :Example:

    >>> a = array()
    >>> a.add_line(1, 2, 3)
    >>> a.add_line(4, 5, 6)
    >>> a.add_line(indent="")
    >>> print(a.as_string())
    [
        1, 2, 3,
        4, 5, 6,
    ]
